async function analyticsPage(req,env,s,user){if(!await can(env,user,'view_analytics'))return forbidden();const tid=user.tenant_id,stats=await tenantStats(env,tid),top=await all(env,'SELECT pv.url,COUNT(*) c FROM pageviews pv JOIN domains d ON d.id=pv.domain_id WHERE d.tenant_id=? GROUP BY pv.url ORDER BY c DESC LIMIT 10',[tid]),rows=top.map(x=>`<div class="metric-row"><span>${e(x.url)}</span><b>${Number(x.c)}</b></div>`).join('');return render(req,env,s,user,'Analytics',`<div class="page-head"><div><span class="eyebrow">REALTIME DATA • CLOUDFLARE</span><h1>Traffic Analytics</h1></div></div><div class="stats">${stat('Online',stats.online,'pulse')}${stat('Pageviews hari ini',stats.views_today,'trend')}${stat('Open chat',stats.open_chats,'chat')}${stat('Total chat',stats.all_chats,'chat')}</div><div class="grid-2"><section class="panel"><h2>24 jam terakhir</h2><div class="big-chart mini-chart" data-chart='${attr(JSON.stringify(stats.hourly))}'></div></section><section class="panel"><h2>Halaman teratas</h2>${rows||'<div class="empty">Belum ada data.</div>'}</section></div>`,true);}

async function visitorsPage(req,env,s,user){if(!await can(env,user,'view_analytics'))return forbidden();const tid=user.tenant_id,cutoff=new Date(Date.now()-90000).toISOString().replace('T',' ').replace('Z','').slice(0,19),vs=await all(env,'SELECT v.*,d.domain FROM visitors v JOIN domains d ON d.id=v.domain_id WHERE d.tenant_id=? ORDER BY v.last_seen_at DESC LIMIT 250',[tid]),rows=vs.map(v=>{const online=v.last_seen_at>=cutoff;return `<div class="visitor-row"><span class="presence ${online?'online':'offline'}"></span><div><b>${e(v.domain)}</b><small>${e(v.last_url||'/')}</small></div><div class="visitor-meta"><span>${e(String(v.user_agent||'Unknown').slice(0,38))}</span><small>${e(v.country||'')} • ${e(v.last_seen_at)}</small></div></div>`}).join('');return render(req,env,s,user,'Live Visitors',`<div class="page-head"><div><span class="eyebrow">LIVE REPORT</span><h1>Pengunjung Realtime</h1></div></div><section class="panel"><div class="panel-head"><h2>Aktivitas terbaru</h2><span class="muted">Online = heartbeat ≤ 90 detik</span></div>${rows||'<div class="empty">Belum ada traffic.</div>'}</section>`,true);}

async function notificationsPage(req,env,ctx,s,user){if(!await can(env,user,'manage_notifications')&&user.role!=='owner')return forbidden();let pref=await one(env,'SELECT * FROM user_preferences WHERE user_id=?',[user.id]),err='';if(req.method==='POST'){
  const fd=await req.formData();const b=Object.fromEntries(fd.entries());if(!csrfOk(req,s,b))err='CSRF tidak valid.';else try{let asset=pref?.sound_asset_key||null;const file=fd.get('sound_file');if(file&&typeof file==='object'&&Number(file.size)>0){if(file.size>2*1024*1024)throw new Error('File nada maksimal 2 MB.');if(!['audio/mpeg','audio/ogg','audio/wav','audio/x-wav','audio/mp4'].includes(file.type))throw new Error('Format nada harus MP3/OGG/WAV/M4A.');const key=`sounds/u${user.id}/${randomToken(18)}.${mimeExt(file.type)}`;await env.UPLOADS.put(key,file.stream(),{httpMetadata:{contentType:file.type}});await insert(env,'INSERT INTO media_assets(tenant_id,user_id,kind,r2_key,mime,size,created_at) VALUES(?,?,\'sound\',?,?,?,?)',[user.tenant_id,user.id,key,file.type,file.size,nowIso()]);if(asset)await env.UPLOADS.delete(asset).catch(()=>{});asset=key;}const notifications={new_chat:!!b.new_chat,visitor_online:!!b.visitor_online,security:!!b.security};await run(env,'UPDATE user_preferences SET sound=?,sound_asset_key=?,notifications_json=?,updated_at=? WHERE user_id=?',[['soft','crisp','digital','custom','none'].includes(b.sound)?b.sound:'soft',asset,JSON.stringify(notifications),nowIso(),user.id]);await audit(env,ctx,{event:'NOTIFICATION_SETTINGS_CHANGED',risk:5,tenantId:user.tenant_id,userId:user.id,request:req});flash(s,'ok','Pengaturan notifikasi disimpan.');return redirect('/notifications');}catch(x){err=x.message;}}
  pref=await one(env,'SELECT * FROM user_preferences WHERE user_id=?',[user.id]);let n={};try{n=JSON.parse(pref.notifications_json||'{}')}catch{}const body=`<div class="page-head"><div><span class="eyebrow">PERSONAL ALERT</span><h1>Nada & Notifikasi</h1></div></div>${err?`<div class="alert error">${e(err)}</div>`:''}<div class="grid-2"><section class="panel"><form method="post" enctype="multipart/form-data">${csrfField(s)}<label>Profil suara<select name="sound"><option value="soft"${selected(pref.sound,'soft')}>Soft</option><option value="crisp"${selected(pref.sound,'crisp')}>Crisp</option><option value="digital"${selected(pref.sound,'digital')}>Digital</option><option value="custom"${selected(pref.sound,'custom')}>Custom Upload</option><option value="none"${selected(pref.sound,'none')}>Off</option></select></label><label>Upload nada custom<input type="file" name="sound_file" accept="audio/*"></label><label class="switch-row"><input type="checkbox" name="new_chat" value="1" ${n.new_chat!==false?'checked':''}> Chat baru</label><label class="switch-row"><input type="checkbox" name="visitor_online" value="1" ${n.visitor_online?'checked':''}> Visitor baru</label><label class="switch-row"><input type="checkbox" name="security" value="1" ${n.security!==false?'checked':''}> Security alert</label><button class="btn primary">Simpan Notifikasi</button></form></section><section class="panel"><h2>Isolasi per user</h2><p class="muted">Setiap akun menyimpan profil nada sendiri. Custom audio disimpan private di Cloudflare R2 dan hanya dapat diakses setelah login.</p><button type="button" id="testSound" class="btn ghost">Test Nada</button></section></div>`;return render(req,env,s,user,'Notifications',body,true);
}
function mimeExt(m){return {'audio/mpeg':'mp3','audio/ogg':'ogg','audio/wav':'wav','audio/x-wav':'wav','audio/mp4':'m4a','image/png':'png','image/jpeg':'jpg','image/webp':'webp','image/svg+xml':'svg'}[m]||'bin';}

async function automationPage(req,env,ctx,s,user){if(!await can(env,user,'manage_automation')&&user.role!=='owner')return forbidden();const tid=user.tenant_id;let err='';if(req.method==='POST'){const b=await form(req);if(!csrfOk(req,s,b))err='CSRF tidak valid.';else try{if(b.action==='quick_add'){const shortcut=String(b.shortcut||'').trim().toLowerCase().replace(/[^a-z0-9_-]/g,'').slice(0,30);if(!shortcut||!b.body)throw new Error('Shortcut/body wajib.');await run(env,'INSERT INTO quick_replies(tenant_id,shortcut,body,created_at) VALUES(?,?,?,?) ON CONFLICT(tenant_id,shortcut) DO UPDATE SET body=excluded.body',[tid,shortcut,cap(b.body,3000),nowIso()]);}else if(b.action==='quick_delete')await run(env,'DELETE FROM quick_replies WHERE id=? AND tenant_id=?',[Number(b.id),tid]);else if(b.action==='rule_add'){await insert(env,'INSERT INTO automation_rules(tenant_id,name,event_type,action_type,action_json,enabled,created_at) VALUES(?,?,?,?,?,1,?)',[tid,cap(b.name,100),b.event_type,b.action_type,JSON.stringify({message:cap(b.message,1000)}),nowIso()]);}else if(b.action==='rule_delete')await run(env,'DELETE FROM automation_rules WHERE id=? AND tenant_id=?',[Number(b.id),tid]);await audit(env,ctx,{event:'AUTOMATION_CHANGED',risk:10,tenantId:tid,userId:user.id,request:req});return redirect('/automation');}catch(x){err=x.message;}}
  const quick=await all(env,'SELECT * FROM quick_replies WHERE tenant_id=? ORDER BY shortcut',[tid]),rules=await all(env,'SELECT * FROM automation_rules WHERE tenant_id=? ORDER BY id DESC',[tid]);const qrows=quick.map(q=>`<div class="list-row"><div><b>/${e(q.shortcut)}</b><small>${e(q.body.slice(0,100))}</small></div><form method="post">${csrfField(s)}<input type="hidden" name="action" value="quick_delete"><input type="hidden" name="id" value="${q.id}"><button class="btn small danger">Hapus</button></form></div>`).join('')||'<div class="empty">Belum ada quick reply.</div>',rrows=rules.map(r=>`<div class="list-row"><div><b>${e(r.name)}</b><small>${e(r.event_type)} → ${e(r.action_type)}</small></div><form method="post">${csrfField(s)}<input type="hidden" name="action" value="rule_delete"><input type="hidden" name="id" value="${r.id}"><button class="btn small danger">Hapus</button></form></div>`).join('')||'<div class="empty">Belum ada automation.</div>';
  return render(req,env,s,user,'Automation',`<div class="page-head"><div><span class="eyebrow">WORKFLOW</span><h1>Automation & Quick Reply</h1></div></div>${err?`<div class="alert error">${e(err)}</div>`:''}<div class="grid-2"><section class="panel"><h2>Quick Reply</h2><form method="post">${csrfField(s)}<input type="hidden" name="action" value="quick_add"><label>Shortcut<input name="shortcut" placeholder="cek_transaksi" required></label><label>Balasan<textarea name="body" required></textarea></label><button class="btn primary">Simpan</button></form>${qrows}</section><section class="panel"><h2>Automation Rule</h2><form method="post">${csrfField(s)}<input type="hidden" name="action" value="rule_add"><label>Nama<input name="name" required></label><label>Event<select name="event_type"><option>CHAT_NEW</option><option>VISITOR_NEW</option><option>DOMAIN_ADD</option></select></label><label>Action<select name="action_type"><option>telegram_notify</option><option>webhook</option><option>auto_reply</option></select></label><label>Pesan / payload<textarea name="message"></textarea></label><button class="btn primary">Tambah Rule</button></form>${rrows}</section></div>`,true);
}

async function apiWebhooksPage(req,env,ctx,s,user){if(!await can(env,user,'manage_api')&&user.role!=='owner')return forbidden();const tid=user.tenant_id;let err='',newKey='';if(req.method==='POST'){const b=await form(req);if(!csrfOk(req,s,b))err='CSRF tidak valid.';else try{if(b.action==='api_add'){const raw='jlc_'+randomToken(32);newKey=raw;await insert(env,'INSERT INTO api_keys(tenant_id,name,key_hash,prefix,status,created_at) VALUES(?,?,?,?,\'active\',?)',[tid,cap(b.name,100),await sha256(raw),raw.slice(0,12),nowIso()]);await audit(env,ctx,{event:'API_KEY_CREATED',risk:30,metadata:{name:b.name},tenantId:tid,userId:user.id,request:req});}else if(b.action==='api_delete'){await run(env,'UPDATE api_keys SET status=\'revoked\' WHERE id=? AND tenant_id=?',[Number(b.id),tid]);await audit(env,ctx,{event:'API_KEY_REVOKED',risk:30,metadata:{id:Number(b.id)},tenantId:tid,userId:user.id,request:req});}else if(b.action==='hook_add'){if(!/^https:\/\//i.test(String(b.url||'')))throw new Error('Webhook wajib HTTPS.');const sec=randomToken(32);await insert(env,'INSERT INTO outbound_webhooks(tenant_id,name,url,secret_enc,event_types,status,created_at) VALUES(?,?,?,?,?,\'active\',?)',[tid,cap(b.name,100),cap(b.url,1000),await vaultEncrypt(env,sec),cap(b.events||'*',1000),nowIso()]);newKey=`Webhook signing secret: ${sec}`;await audit(env,ctx,{event:'OUTBOUND_WEBHOOK_CREATED',risk:30,tenantId:tid,userId:user.id,request:req});}else if(b.action==='hook_delete')await run(env,'DELETE FROM outbound_webhooks WHERE id=? AND tenant_id=?',[Number(b.id),tid]);}catch(x){err=x.message;}}
  const keys=await all(env,'SELECT * FROM api_keys WHERE tenant_id=? ORDER BY id DESC',[tid]),hooks=await all(env,'SELECT * FROM outbound_webhooks WHERE tenant_id=? ORDER BY id DESC',[tid]),krows=keys.map(k=>`<div class="list-row"><div><b>${e(k.name)}</b><small>${e(k.prefix)}•••• • ${e(k.status)}</small></div><form method="post">${csrfField(s)}<input type="hidden" name="action" value="api_delete"><input type="hidden" name="id" value="${k.id}"><button class="btn small danger">Revoke</button></form></div>`).join(''),hrows=hooks.map(h=>`<div class="list-row"><div><b>${e(h.name)}</b><small>${e(h.url)}</small></div><form method="post">${csrfField(s)}<input type="hidden" name="action" value="hook_delete"><input type="hidden" name="id" value="${h.id}"><button class="btn small danger">Hapus</button></form></div>`).join('');
  return render(req,env,s,user,'API & Webhooks',`<div class="page-head"><div><span class="eyebrow">DEVELOPER</span><h1>API & Outbound Webhook</h1></div></div>${err?`<div class="alert error">${e(err)}</div>`:''}${newKey?`<div class="alert ok"><b>Simpan sekarang. Secret hanya ditampilkan sekali.</b><code class="codebox">${e(newKey)}</code></div>`:''}<div class="grid-2"><section class="panel"><h2>API Keys</h2><form method="post">${csrfField(s)}<input type="hidden" name="action" value="api_add"><label>Nama key<input name="name" required></label><button class="btn primary">Buat API Key</button></form>${krows}</section><section class="panel"><h2>Outbound Webhook</h2><form method="post">${csrfField(s)}<input type="hidden" name="action" value="hook_add"><label>Nama<input name="name" required></label><label>HTTPS URL<input type="url" name="url" required></label><label>Events<input name="events" value="CHAT_NEW,LOGIN_SUCCESS" placeholder="* atau EVENT1,EVENT2"></label><button class="btn primary">Tambah Webhook</button></form>${hrows}</section></div><section class="panel"><h2>REST API</h2><code class="codebox">GET ${e(baseUrl(req))}/api/v1/chats\nPOST ${e(baseUrl(req))}/api/v1/chats/{id}/messages\nAuthorization: Bearer jlc_...</code></section>`,true);
}

async function subscriptionPage(req,env,ctx,s,user){if(!['owner','super_admin'].includes(user.role))return forbidden();const tid=user.tenant_id;if(req.method==='POST'){const b=await form(req);if(csrfOk(req,s,b)){const pid=Number(b.plan_id);if(!await one(env,"SELECT id FROM upgrade_requests WHERE tenant_id=? AND status='pending'",[tid]))await insert(env,"INSERT INTO upgrade_requests(tenant_id,plan_id,status,note,created_at) VALUES(?,?,'pending',?,?)",[tid,pid,cap(b.note,500),nowIso()]);await audit(env,ctx,{event:'UPGRADE_REQUEST',risk:10,metadata:{plan_id:pid},tenantId:tid,userId:user.id,request:req});flash(s,'ok','Permintaan upgrade dikirim ke admin.');}return redirect('/subscription');}const current=await currentPlan(env,tid),plans=await all(env,'SELECT * FROM plans WHERE is_active=1 ORDER BY price'),cards=plans.map(p=>`<div class="plan-card ${Number(current?.id)===Number(p.id)?'current':''}"><span class="pill">${e(p.name)}</span><h2>Rp ${money(p.price)}</h2><p>${p.domain_limit} domain • ${p.bot_limit} bot • ${p.agent_limit} user</p><form method="post">${csrfField(s)}<input type="hidden" name="plan_id" value="${p.id}"><button class="btn ${Number(current?.id)===Number(p.id)?'ghost':'primary'} full" ${Number(current?.id)===Number(p.id)?'disabled':''}>${Number(current?.id)===Number(p.id)?'Paket aktif':'Request Upgrade'}</button></form></div>`).join('');return render(req,env,s,user,'Subscription',`<div class="page-head"><div><span class="eyebrow">SUBSCRIPTION</span><h1>Upgrade Langganan</h1></div><div class="plan-chip">Berakhir ${e(String(current?.ends_at||'-').slice(0,10))}</div></div><div class="plan-grid">${cards}</div>`,true);}

async function diagnosticsPage(req,env,s,user){if(!await can(env,user,'diagnostics')&&user.role!=='owner')return forbidden();const tid=user.tenant_id,domains=await all(env,'SELECT * FROM domains WHERE tenant_id=?',[tid]);let rows='';for(const d of domains){const bot=await domainBot(env,d.id);let wh='not connected',botOk=false;if(bot){const r=await tgCall(bot.token,'getWebhookInfo');botOk=!!r.ok;wh=r.ok?(r.result?.url||'webhook empty'):(r.description||'error');}const checks=[['Domain status',d.status==='active',d.status],['Widget config',!!await one(env,'SELECT domain_id FROM widget_settings WHERE domain_id=?',[d.id]),'configured'],['Telegram bot',!!bot,bot?`@${bot.bot_username}`:'not connected'],['Telegram webhook',botOk,wh],['HTTPS Worker',true,baseUrl(req)]];rows+=`<section class="panel"><div class="panel-head"><h2>${e(d.domain)}</h2><span class="badge ${e(d.status)}">${e(d.status)}</span></div>${checks.map(x=>`<div class="diag-row"><span class="diag-icon ${x[1]?'ok':'bad'}">${x[1]?'✓':'!'}</span><div><b>${e(x[0])}</b><small>${e(x[2])}</small></div></div>`).join('')}</section>`;}
  const server=[['Runtime: Cloudflare Workers',true],['Database: D1',!!env.DB],['Storage: R2',!!env.UPLOADS],['Realtime: Durable Objects',!!env.LIVE_HUB],['Security Vault',await vaultReady(env)],['HTTPS',new URL(req.url).protocol==='https:'],['Cron maintenance',true]];return render(req,env,s,user,'Diagnostics',`<div class="page-head"><div><span class="eyebrow">SYSTEM DOCTOR</span><h1>Diagnosis & Troubleshooting</h1></div></div><section class="panel"><h2>Cloudflare health</h2>${server.map(x=>`<div class="diag-row"><span class="diag-icon ${x[1]?'ok':'bad'}">${x[1]?'✓':'!'}</span><b>${e(x[0])}</b></div>`).join('')}</section><div class="cards">${rows}</div><section class="panel"><h2>Tutorial cepat</h2><details><summary>Widget tidak tampil</summary><p>Pastikan domain status <b>active</b>, script memakai <code>data-site</code> yang benar, origin sama dengan domain terdaftar, dan halaman HTTPS.</p></details><details><summary>Chat tidak masuk Telegram</summary><p>Pastikan bot sudah pairing, domain dipetakan ke bot, webhook Telegram aktif, dan bot tidak dipakai domain lain.</p></details><details><summary>OTP tidak masuk</summary><p>Pastikan user menekan Start pada bot autentikasi. Cek Admin → Settings → getWebhookInfo.</p></details><details><summary>Error Cloudflare</summary><p>Jalankan <code>npx wrangler tail</code>. Pastikan D1/R2/Durable Objects berhasil diprovision otomatis.</p></details></section>`,true);}

async function settingsPage(req,env,ctx,s,user){let pref=await one(env,'SELECT * FROM user_preferences WHERE user_id=?',[user.id]);if(req.method==='POST'){const b=await form(req);if(csrfOk(req,s,b)){await run(env,'UPDATE users SET name=? WHERE id=?',[cap(b.name,120),user.id]);await run(env,'UPDATE user_preferences SET theme=?,sound=?,updated_at=? WHERE user_id=?',[['system','dark','light'].includes(b.theme)?b.theme:'system',['soft','crisp','digital','custom','none'].includes(b.sound)?b.sound:'soft',nowIso(),user.id]);await audit(env,ctx,{event:'ACCOUNT_SETTINGS_CHANGED',risk:10,tenantId:user.tenant_id,userId:user.id,request:req});flash(s,'ok','Pengaturan disimpan.');}return redirect('/settings');}pref=await one(env,'SELECT * FROM user_preferences WHERE user_id=?',[user.id]);return render(req,env,s,user,'Account Settings',`<div class="page-head"><div><span class="eyebrow">PROFILE</span><h1>Setting Akun</h1></div></div><div class="grid-2"><section class="panel"><form method="post">${csrfField(s)}<label>Nama<input name="name" value="${attr(user.name)}"></label><label>Email<input value="${attr(user.email)}" disabled></label><label>Theme<select name="theme"><option value="system"${selected(pref?.theme,'system')}>System</option><option value="dark"${selected(pref?.theme,'dark')}>Dark</option><option value="light"${selected(pref?.theme,'light')}>Light</option></select></label><label>Nada notifikasi<select name="sound"><option value="soft"${selected(pref?.sound,'soft')}>Soft</option><option value="crisp"${selected(pref?.sound,'crisp')}>Crisp</option><option value="digital"${selected(pref?.sound,'digital')}>Digital</option><option value="custom"${selected(pref?.sound,'custom')}>Custom</option><option value="none"${selected(pref?.sound,'none')}>Off</option></select></label><button class="btn primary">Simpan</button></form></section><section class="panel"><h2>Telegram Security</h2><div class="identity-card"><b>@${e(user.telegram_username||'belum-terhubung')}</b><small>ID ${e(user.telegram_user_id||'-')}</small><span class="badge ${user.telegram_verified_at?'active':'pending'}">${user.telegram_verified_at?'verified':'not linked'}</span></div><p class="muted">Telegram User ID menjadi identitas utama verifikasi, bukan username yang bisa berubah.</p></section></div>`,true);}

async function adminPage(req,env,ctx,s,user,url){if(user.role!=='super_admin')return forbidden();const p=url.pathname;
  if(p==='/admin'||p==='/admin/dashboard'){const counts={users:Number((await one(env,'SELECT COUNT(*) c FROM users'))?.c||0),tenants:Number((await one(env,'SELECT COUNT(*) c FROM tenants'))?.c||0),domains:Number((await one(env,'SELECT COUNT(*) c FROM domains'))?.c||0),online:Number((await one(env,'SELECT COUNT(*) c FROM visitors WHERE last_seen_at>=?',[new Date(Date.now()-90000).toISOString().replace('T',' ').replace('Z','').slice(0,19)]))?.c||0)},logs=await all(env,'SELECT * FROM audit_logs ORDER BY id DESC LIMIT 20'),rows=logs.map(l=>`<div class="list-row"><div><b>${e(l.event_type)}</b><small>${e(l.created_at)} • User #${e(l.user_id||'-')}</small></div><span class="risk ${Number(l.risk)>=50?'high':''}">${l.risk}</span></div>`).join('');return render(req,env,s,user,'Admin',`<div class="page-head"><div><span class="eyebrow">SUPER ADMIN • CLOUDFLARE</span><h1>Platform Overview</h1></div></div><div class="stats">${stat('Users',counts.users,'user')}${stat('Tenants',counts.tenants,'domain')}${stat('Domains',counts.domains,'domain')}${stat('Online',counts.online,'pulse')}</div><section class="panel"><div class="panel-head"><h2>Security Event Stream</h2><a href="/admin/logs">View logs</a></div>${rows}</section>`,true,true);}
  if(p==='/admin/settings')return adminSettingsPage(req,env,ctx,s,user);
  if(p==='/admin/users'){const rows=(await all(env,'SELECT u.*,t.name tenant_name FROM users u LEFT JOIN tenants t ON t.id=u.tenant_id ORDER BY u.id DESC LIMIT 300')).map(x=>`<div class="list-row"><div><b>${e(x.name)} • ${e(x.email)}</b><small>${e(x.tenant_name)} • ${e(x.role)}</small></div><span class="badge ${e(x.status)}">${e(x.status)}</span></div>`).join('');return render(req,env,s,user,'Admin Users',`<div class="page-head"><h1>Users</h1></div><section class="panel">${rows}</section>`,true,true);}
  if(p==='/admin/plans')return adminPlansPage(req,env,ctx,s,user);
  if(p==='/admin/subscriptions')return adminSubscriptionsPage(req,env,ctx,s,user);
  if(p==='/admin/logs'){const logs=await all(env,'SELECT * FROM audit_logs ORDER BY id DESC LIMIT 500'),rows=logs.map(l=>`<div class="list-row"><div><b>${e(l.event_type)}</b><small>User #${e(l.user_id||'-')} • ${e(l.ip||'')} • ${e(l.created_at)}</small></div><span class="risk ${Number(l.risk)>=50?'high':''}">${Number(l.risk)}</span></div>`).join('');return render(req,env,s,user,'Audit Logs',`<div class="page-head"><h1>Audit Logs</h1></div><section class="panel">${rows}</section>`,true,true);}
  return render(req,env,s,user,'Admin 404','<div class="empty">Admin page not found.</div>',true,true,404);
}

async function adminSettingsPage(req,env,ctx,s,user){let err='',info='';if(req.method==='POST'){const b=await form(req);if(!csrfOk(req,s,b))err='CSRF tidak valid.';else try{
    if(b.action==='auth_bot'){const token=normalizeToken(b.token),me=await tgCall(token,'getMe');if(!me.ok)throw new Error(me.transport_error?`Server Cloudflare gagal menghubungi Telegram: ${me.description}`:`Token bot autentikasi tidak valid: ${me.description||''}`);const username=me.result?.username||'',secret=secretToken(40);await saveAuthBot(env,{token,username,webhook_secret:secret});const wh=await tgCall(token,'setWebhook',{url:`${baseUrl(req)}/webhook/auth/${secret}`,secret_token:secret,drop_pending_updates:true,allowed_updates:['message']});if(!wh.ok)throw new Error(`setWebhook gagal: ${wh.description||'unknown'}`);const check=await tgCall(token,'getWebhookInfo');info=check.ok?`Webhook aktif: ${check.result?.url||'-'}`:'Webhook tersimpan, getWebhookInfo gagal.';await audit(env,ctx,{event:'AUTH_BOT_CHANGED',risk:50,metadata:{username},tenantId:user.tenant_id,userId:user.id,request:req});
    }else if(b.action==='link_admin'){const token=randomToken(40).slice(0,60);await run(env,"INSERT INTO telegram_links(user_id,token,purpose,expires_at,created_at) VALUES(?,?,'link_only',?,?)",[user.id,token,isoAfter(1800),nowIso()]);return redirect(`/telegram/connect?token=${encodeURIComponent(token)}`);
    }else if(b.action==='admin_bot_add'){const token=normalizeToken(b.token),me=await tgCall(token,'getMe');if(!me.ok)throw new Error(`Token tracking bot tidak valid: ${me.description||''}`);await insert(env,"INSERT INTO admin_bots(name,token_enc,chat_id,event_types,status,created_at) VALUES(?,?,?,?, 'active',?)",[cap(b.name,100),await vaultEncrypt(env,token),cap(b.chat_id,80),cap(b.events||'*',1000),nowIso()]);await audit(env,ctx,{event:'ADMIN_TRACKING_BOT_ADD',risk:40,metadata:{name:b.name},tenantId:user.tenant_id,userId:user.id,request:req});
    }else if(b.action==='admin_bot_delete'){await run(env,'DELETE FROM admin_bots WHERE id=?',[Number(b.id)]);}
    if(info)flash(s,'ok',info);return redirect('/admin/settings');
  }catch(x){err=x.message;}}
  const bot=await authBot(env),abots=await all(env,'SELECT id,name,chat_id,event_types,status,created_at FROM admin_bots ORDER BY id DESC'),ab=abots.map(x=>`<div class="list-row"><div><b>${e(x.name)}</b><small>${e(x.chat_id)} • ${e(x.event_types)}</small></div><form method="post">${csrfField(s)}<input type="hidden" name="action" value="admin_bot_delete"><input type="hidden" name="id" value="${x.id}"><button class="btn small danger">Hapus</button></form></div>`).join('')||'<div class="empty">Belum ada tracking bot.</div>';
  const content=`<div class="page-head"><div><span class="eyebrow">PLATFORM SETTINGS</span><h1>Bot & Security Router</h1></div></div>${err?`<div class="alert error">${e(err)}</div>`:''}${info?`<div class="alert ok">${e(info)}</div>`:''}<div class="grid-2"><section class="panel"><h2>Bot Autentikasi</h2><p class="muted">Pairing + OTP register/login/reset.</p><form method="post">${csrfField(s)}<input type="hidden" name="action" value="auth_bot"><label>Bot Token<input type="password" name="token" required autocomplete="off"></label><label>Bot Username<input value="${attr(bot?.username?`@${bot.username}`:'otomatis dari getMe')}" disabled></label><button class="btn primary">Simpan & Pasang Webhook</button></form><form method="post" style="margin-top:10px">${csrfField(s)}<input type="hidden" name="action" value="link_admin"><button class="btn ghost full">Hubungkan Telegram Admin</button></form></section><section class="panel"><h2>Admin Tracking Bot</h2><form method="post">${csrfField(s)}<input type="hidden" name="action" value="admin_bot_add"><label>Nama<input name="name" required></label><label>Token<input type="password" name="token" required></label><label>Chat ID<input name="chat_id" required></label><label>Event types<input name="events" value="LOGIN_SUCCESS,PASSWORD_RESET,DOMAIN_ADD,BOT_ADD" placeholder="* atau EVENT1,EVENT2"></label><button class="btn primary">Tambah Bot</button></form></section></div><section class="panel"><h2>Tracking bots</h2>${ab}</section>`;
  return render(req,env,s,user,'Admin Settings',content,true,true);
}

async function adminPlansPage(req,env,ctx,s,user){if(req.method==='POST'){const b=await form(req);if(csrfOk(req,s,b)){await run(env,'UPDATE plans SET price=?,duration_days=?,domain_limit=?,bot_limit=?,agent_limit=?,history_days=?,is_active=? WHERE id=?',[safeInt(b.price),safeInt(b.duration_days,30),safeInt(b.domain_limit,1),safeInt(b.bot_limit,1),safeInt(b.agent_limit,1),safeInt(b.history_days,30),b.is_active?1:0,Number(b.id)]);await audit(env,ctx,{event:'PLAN_CHANGED',risk:50,metadata:{plan_id:Number(b.id)},tenantId:user.tenant_id,userId:user.id,request:req});}return redirect('/admin/plans');}const plans=await all(env,'SELECT * FROM plans ORDER BY price'),cards=plans.map(x=>`<form method="post" class="panel">${csrfField(s)}<input type="hidden" name="id" value="${x.id}"><h2>${e(x.name)}</h2><div class="form-grid"><label>Harga<input type="number" name="price" value="${x.price}"></label><label>Hari<input type="number" name="duration_days" value="${x.duration_days}"></label><label>Domain<input type="number" name="domain_limit" value="${x.domain_limit}"></label><label>Bot<input type="number" name="bot_limit" value="${x.bot_limit}"></label><label>User<input type="number" name="agent_limit" value="${x.agent_limit}"></label><label>History<input type="number" name="history_days" value="${x.history_days}"></label></div><label class="switch-row"><input type="checkbox" name="is_active" value="1"${checked(x.is_active)}> Aktif</label><button class="btn primary">Simpan Plan</button></form>`).join('');return render(req,env,s,user,'Admin Plans',`<div class="page-head"><h1>Plan Builder</h1></div><div class="cards">${cards}</div>`,true,true);}

