async function webhookRoute(req,env,ctx,url){
  const authMatch=url.pathname.match(/^\/webhook\/auth\/([A-Za-z0-9_-]+)$/);if(authMatch)return authWebhook(req,env,ctx,authMatch[1]);
  const botMatch=url.pathname.match(/^\/webhook\/bot\/(\d+)\/([A-Za-z0-9_-]+)$/);if(botMatch)return botWebhook(req,env,ctx,Number(botMatch[1]),botMatch[2]);return json({ok:false},404);
}

async function authWebhook(req,env,ctx,pathSecret){
  const bot=await authBot(env);if(!bot||bot.webhook_secret!==pathSecret)return json({ok:false},403);const got=req.headers.get('x-telegram-bot-api-secret-token')||'';if(got!==pathSecret)return json({ok:false},403);const up=await req.json().catch(()=>({})),msg=up.message;if(!msg?.text)return json({ok:true});const m=msg.text.match(/^\/start\s+([A-Za-z0-9_-]{8,80})/);if(m){const link=await one(env,'SELECT * FROM telegram_links WHERE token=?',[m[1]]);const ok=await pairTelegram(env,ctx,req,m[1],msg.from,msg.chat?.id);if(ok){const note=link?.purpose==='link_only'?'✅ Telegram berhasil dihubungkan ke akun.':'✅ Telegram berhasil terhubung. OTP verifikasi sudah dikirim.';await tgSend(bot.token,String(msg.chat.id),note);}}return json({ok:true});
}

async function botWebhook(req,env,ctx,id,pathSecret){
  const b=await one(env,"SELECT * FROM bots WHERE id=? AND status='active'",[id]);if(!b||b.webhook_secret!==pathSecret)return json({ok:false},403);if((req.headers.get('x-telegram-bot-api-secret-token')||'')!==pathSecret)return json({ok:false},403);const up=await req.json().catch(()=>({})),msg=up.message;if(!msg?.text)return json({ok:true});
  const bind=msg.text.match(/^\/(?:start\s+bind_|bind\s+)([A-Za-z0-9_-]+)/);if(bind&&bind[1]===b.bind_token){await run(env,'UPDATE bots SET notification_chat_id=? WHERE id=?',[String(msg.chat.id),id]);const token=await vaultDecrypt(env,b.token_enc);await tgSend(token,String(msg.chat.id),'✅ Bot live chat berhasil dihubungkan. Chat dari website akan masuk ke percakapan ini.');await audit(env,ctx,{event:'BOT_CHAT_BOUND',risk:10,metadata:{bot_id:id,chat_id:String(msg.chat.id)},tenantId:b.tenant_id,request:req});return json({ok:true});}
  if(b.notification_chat_id&&String(msg.chat?.id)!==String(b.notification_chat_id))return json({ok:true});let chat=null,body=msg.text;
  if(msg.reply_to_message?.message_id)chat=await one(env,'SELECT c.*,v.visitor_key FROM messages m JOIN chats c ON c.id=m.chat_id JOIN visitors v ON v.id=c.visitor_id JOIN domain_bots db ON db.domain_id=c.domain_id WHERE m.telegram_message_id=? AND db.bot_id=? ORDER BY m.id DESC LIMIT 1',[String(msg.reply_to_message.message_id),id]);
  if(!chat){const mm=body.match(/^\/reply\s+([A-Z0-9]{6,12})\s+([\s\S]+)/);if(mm){chat=await one(env,'SELECT c.*,v.visitor_key FROM chats c JOIN visitors v ON v.id=c.visitor_id JOIN domain_bots db ON db.domain_id=c.domain_id WHERE c.code=? AND db.bot_id=?',[mm[1],id]);body=mm[2];}}
  if(chat&&body.trim()){const mid=await insert(env,"INSERT INTO messages(chat_id,sender_type,sender_id,body,created_at) VALUES(?,'agent',?,?,?)",[chat.id,`telegram:${msg.from?.id||''}`,cap(body.trim(),3500),nowIso()]);await run(env,'UPDATE chats SET updated_at=? WHERE id=?',[nowIso(),chat.id]);await hubBroadcast(env,chat.domain_id,{type:'message',id:mid,chat_id:chat.id,visitor_key:chat.visitor_key,sender_type:'agent',body:cap(body.trim(),3500),created_at:nowIso()});await audit(env,ctx,{event:'TELEGRAM_REPLY',risk:5,metadata:{chat:chat.code},tenantId:b.tenant_id,request:req});}
  return json({ok:true});
}

async function parseWidgetBody(req){if(req.method==='GET')return {};const raw=await req.text();if(!raw)return {};try{return JSON.parse(raw)}catch{return {}}}
function corsHeaders(req,domain){const origin=req.headers.get('origin')||'';const h={'access-control-allow-methods':'GET,POST,OPTIONS','access-control-allow-headers':'Content-Type','access-control-max-age':'86400','vary':'Origin'};if(origin&&sameDomain(originHost(origin),domain))h['access-control-allow-origin']=origin;return h;}
function widgetOriginOk(req,domain){const source=req.headers.get('origin')||req.headers.get('referer')||'';return !source||sameDomain(originHost(source),domain);}
function widgetJson(req,domain,data,status=200){return json(data,status,corsHeaders(req,domain));}
async function widgetSite(env,site){return one(env,`SELECT d.*,ws.title,ws.welcome,ws.position,ws.theme,ws.accent,ws.icon,ws.custom_icon_key,ws.require_name,ws.require_phone,ws.require_email,ws.offline_message,ws.business_hours_json,ws.launcher_label FROM domains d JOIN widget_settings ws ON ws.domain_id=d.id WHERE d.public_key=? AND d.status='active'`,[site]);}

async function widgetApi(req,env,ctx,url){
  const payload=await parseWidgetBody(req),site=String(payload.site||url.searchParams.get('site')||''),d=await widgetSite(env,site);if(req.method==='OPTIONS')return d?new Response(null,{status:204,headers:corsHeaders(req,d.domain)}):new Response(null,{status:204});if(!d)return json({ok:false,error:'invalid_site'},404);if(!widgetOriginOk(req,d.domain))return widgetJson(req,d.domain,{ok:false,error:'origin_not_allowed'},403);const p=url.pathname;
  if(p==='/api/widget/bootstrap'){let vk=String(payload.visitor_key||'').replace(/[^A-Za-z0-9_-]/g,'');if(vk.length<12)vk=randomToken(18);const v=await touchVisitor(req,env,ctx,d,vk,payload);const open=isBusinessOpen(d.business_hours_json);return widgetJson(req,d.domain,{ok:true,visitor_key:vk,settings:{title:d.title,welcome:open?d.welcome:d.offline_message,position:d.position,theme:d.theme,accent:d.accent,icon:d.icon,custom_icon_url:d.custom_icon_key?`/widget-media/${encodeURIComponent(d.custom_icon_key)}`:null,launcher_label:d.launcher_label,require_name:!!d.require_name,require_phone:!!d.require_phone,require_email:!!d.require_email,online:open}});}
  if(p==='/api/widget/heartbeat'){await touchVisitor(req,env,ctx,d,String(payload.visitor_key||''),payload);return widgetJson(req,d.domain,{ok:true});}
  if(p==='/api/widget/message'){
    const rateKey=await sha256(`${d.id}:${String(payload.visitor_key||'anon')}:${clientIp(req)}`);
    if(!await allowRate(env,'widget_message',rateKey,30,60))return widgetJson(req,d.domain,{ok:false,error:'rate_limited'},429);
    const plan=await currentPlan(env,d.tenant_id);if(!plan)return widgetJson(req,d.domain,{ok:false,error:'subscription_inactive'},402);const body=String(payload.body||'').trim();if(!body||body.length>3500)return widgetJson(req,d.domain,{ok:false,error:'invalid_message'},422);if(d.require_name&&!String(payload.name||'').trim())return widgetJson(req,d.domain,{ok:false,error:'name_required'},422);if(d.require_phone&&!String(payload.phone||'').trim())return widgetJson(req,d.domain,{ok:false,error:'phone_required'},422);if(d.require_email&&!String(payload.email||'').trim())return widgetJson(req,d.domain,{ok:false,error:'email_required'},422);
    const v=await touchVisitor(req,env,ctx,d,String(payload.visitor_key||''),payload);let chat=await one(env,"SELECT * FROM chats WHERE domain_id=? AND visitor_id=? AND status='open' ORDER BY id DESC LIMIT 1",[d.id,v.id]);let fresh=false;if(!chat){const code=chatCode(),cid=await insert(env,"INSERT INTO chats(domain_id,visitor_id,code,name,phone,email,status,created_at,updated_at) VALUES(?,?,?,?,?,?,'open',?,?)",[d.id,v.id,code,cap(payload.name,100),cap(payload.phone,40),cap(payload.email,160),nowIso(),nowIso()]);chat=await one(env,'SELECT * FROM chats WHERE id=?',[cid]);fresh=true;await audit(env,ctx,{event:'CHAT_NEW',risk:5,metadata:{domain:d.domain,chat:chat.code},tenantId:d.tenant_id,request:req});}
    const mid=await insert(env,"INSERT INTO messages(chat_id,sender_type,body,created_at) VALUES(?,'visitor',?,?)",[chat.id,body,nowIso()]);await run(env,'UPDATE chats SET updated_at=? WHERE id=?',[nowIso(),chat.id]);const bot=await domainBot(env,d.id);if(bot?.notification_chat_id){const txt=`💬 <b>LIVE CHAT #${e(chat.code)}</b>\nDomain: ${e(d.domain)}\nVisitor: ${e(chat.name||'Anonymous')}\n\n${e(body)}\n\nBalas pesan ini untuk reply ke visitor.`;const tr=await tgSend(bot.token,bot.notification_chat_id,txt);if(tr.ok)await run(env,'UPDATE messages SET telegram_message_id=? WHERE id=?',[String(tr.result?.message_id||''),mid]);}
    await hubBroadcast(env,d.id,{type:'message',id:mid,chat_id:chat.id,visitor_key:v.visitor_key,sender_type:'visitor',body,created_at:nowIso()});if(fresh)ctx.waitUntil(runAutomations(env,ctx,'CHAT_NEW',d.tenant_id,{domainId:d.id,chatId:chat.id,visitorKey:v.visitor_key,chatCode:chat.code}).catch(()=>{}));return widgetJson(req,d.domain,{ok:true,chat_code:chat.code,message_id:mid});
  }
  if(p==='/api/widget/poll'){const vk=String(url.searchParams.get('visitor_key')||payload.visitor_key||''),after=Number(url.searchParams.get('after')||0),v=await one(env,'SELECT * FROM visitors WHERE domain_id=? AND visitor_key=?',[d.id,vk]);if(!v)return widgetJson(req,d.domain,{ok:true,messages:[]});const chat=await one(env,"SELECT * FROM chats WHERE domain_id=? AND visitor_id=? AND status='open' ORDER BY id DESC LIMIT 1",[d.id,v.id]);if(!chat)return widgetJson(req,d.domain,{ok:true,messages:[]});const msgs=await all(env,'SELECT id,sender_type,body,created_at FROM messages WHERE chat_id=? AND id>? ORDER BY id ASC',[chat.id,after]);return widgetJson(req,d.domain,{ok:true,messages:msgs,chat_id:chat.id});}
  return widgetJson(req,d.domain,{ok:false},404);
}


async function allowRate(env,bucket,key,limit,windowSeconds){
  const now=Date.now(),row=await one(env,'SELECT count,expires_at FROM rate_limits WHERE bucket=? AND window_key=?',[bucket,key]);
  if(!row||Date.parse(String(row.expires_at||''))<=now){await run(env,`INSERT INTO rate_limits(bucket,window_key,count,expires_at) VALUES(?,?,1,?) ON CONFLICT(bucket,window_key) DO UPDATE SET count=1,expires_at=excluded.expires_at`,[bucket,key,new Date(now+windowSeconds*1000).toISOString()]);return true;}
  if(Number(row.count||0)>=limit)return false;
  await run(env,'UPDATE rate_limits SET count=count+1 WHERE bucket=? AND window_key=?',[bucket,key]);return true;
}

async function touchVisitor(req,env,ctx,d,vk,payload){if(String(vk).length<8)vk=randomToken(18);const ipHash=await vaultDigest(env,clientIp(req)),url=cap(payload.url,1000),ref=cap(payload.referrer,1000);let v=await one(env,'SELECT * FROM visitors WHERE domain_id=? AND visitor_key=?',[d.id,vk]);if(!v){const id=await insert(env,"INSERT INTO visitors(domain_id,visitor_key,ip_hash,user_agent,referrer,last_url,country,status,first_seen_at,last_seen_at) VALUES(?,?,?,?,?,?,?,'online',?,?)",[d.id,vk,ipHash,ua(req),ref,url,cfCountry(req),nowIso(),nowIso()]);v=await one(env,'SELECT * FROM visitors WHERE id=?',[id]);if(url)await insert(env,'INSERT INTO pageviews(domain_id,visitor_id,url,referrer,created_at) VALUES(?,?,?,?,?)',[d.id,id,url,ref,nowIso()]);await audit(env,ctx,{event:'VISITOR_NEW',risk:0,metadata:{domain:d.domain,url},tenantId:d.tenant_id,request:req});ctx.waitUntil(runAutomations(env,ctx,'VISITOR_NEW',d.tenant_id,{domainId:d.id,visitorKey:vk,url}).catch(()=>{}));}else{if(url&&url!==v.last_url)await insert(env,'INSERT INTO pageviews(domain_id,visitor_id,url,referrer,created_at) VALUES(?,?,?,?,?)',[d.id,v.id,url,ref,nowIso()]);await run(env,"UPDATE visitors SET last_url=?,last_seen_at=?,country=?,status='online' WHERE id=?",[url,nowIso(),cfCountry(req),v.id]);v={...v,last_url:url,last_seen_at:nowIso()};}return v;}

function isBusinessOpen(raw){let h={};try{h=JSON.parse(raw||'{}')}catch{};const entries=Object.entries(h).filter(([k])=>['mon','tue','wed','thu','fri','sat','sun'].includes(k));if(!entries.length||entries.every(([,v])=>!v))return true;const zone=h.timezone||'Asia/Jakarta';let parts;try{parts=new Intl.DateTimeFormat('en-GB',{timeZone:zone,weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(new Date())}catch{return true}const day=(parts.find(x=>x.type==='weekday')?.value||'Mon').slice(0,3).toLowerCase(),hh=parts.find(x=>x.type==='hour')?.value||'00',mm=parts.find(x=>x.type==='minute')?.value||'00',range=h[day];if(!range)return false;const m=String(range).match(/^(\d{2}:\d{2})-(\d{2}:\d{2})$/);if(!m)return true;const cur=`${hh}:${mm}`;return cur>=m[1]&&cur<=m[2];}

async function runAutomations(env,ctx,event,tenantId,data){const rules=await all(env,'SELECT * FROM automation_rules WHERE tenant_id=? AND event_type=? AND enabled=1',[tenantId,event]);for(const r of rules){let a={};try{a=JSON.parse(r.action_json||'{}')}catch{};if(r.action_type==='auto_reply'&&data.chatId&&a.message){const mid=await insert(env,"INSERT INTO messages(chat_id,sender_type,sender_id,body,created_at) VALUES(?,'agent','automation',?,?)",[data.chatId,cap(a.message,1000),nowIso()]);await hubBroadcast(env,data.domainId,{type:'message',id:mid,chat_id:data.chatId,visitor_key:data.visitorKey,sender_type:'agent',body:cap(a.message,1000),created_at:nowIso()});}else if(r.action_type==='telegram_notify'&&data.domainId){const bot=await domainBot(env,data.domainId);if(bot?.notification_chat_id)await tgSend(bot.token,bot.notification_chat_id,`⚡ Automation: ${e(r.name)}\nEvent: ${e(event)}\n${e(a.message||'')}`);}}
}

async function dashboardApi(req,env,ctx,url,s,user){
  const p=url.pathname;if(p==='/api/dashboard/telegram-status'){const token=url.searchParams.get('token')||'',r=await one(env,'SELECT u.telegram_verified_at FROM telegram_links tl JOIN users u ON u.id=tl.user_id WHERE tl.token=?',[token]);return json({ok:true,paired:!!r?.telegram_verified_at});}
  if(!user)return json({ok:false,error:'unauthorized'},401);
  if(p==='/api/dashboard/reply'){
    if(!await can(env,user,'reply_chat'))return json({ok:false,error:'forbidden'},403);const b=await form(req);if(!csrfOk(req,s,b))return json({ok:false,error:'csrf'},403);const cid=Number(b.chat_id||0),body=String(b.body||'').trim();const chat=await one(env,'SELECT c.*,d.tenant_id,v.visitor_key FROM chats c JOIN domains d ON d.id=c.domain_id JOIN visitors v ON v.id=c.visitor_id WHERE c.id=? AND d.tenant_id=?',[cid,user.tenant_id]);if(!chat||!body)return json({ok:false},422);const id=await insert(env,"INSERT INTO messages(chat_id,sender_type,sender_id,body,created_at) VALUES(?,'agent',?,?,?)",[cid,String(user.id),cap(body,3500),nowIso()]);await run(env,'UPDATE chats SET updated_at=? WHERE id=?',[nowIso(),cid]);await hubBroadcast(env,chat.domain_id,{type:'message',id,chat_id:cid,visitor_key:chat.visitor_key,sender_type:'agent',body:cap(body,3500),created_at:nowIso()});return json({ok:true,id});
  }
  if(p==='/api/dashboard/messages'){if(!await can(env,user,'view_chat'))return json({ok:false,error:'forbidden'},403);const cid=Number(url.searchParams.get('chat_id')||0),after=Number(url.searchParams.get('after')||0),valid=await one(env,'SELECT c.id FROM chats c JOIN domains d ON d.id=c.domain_id WHERE c.id=? AND d.tenant_id=?',[cid,user.tenant_id]);if(!valid)return json({ok:false},403);return json({ok:true,messages:await all(env,'SELECT id,sender_type,body,created_at FROM messages WHERE chat_id=? AND id>? ORDER BY id',[cid,after])});}
  if(p==='/api/dashboard/bot-status'){const id=Number(url.searchParams.get('id')||0),b=await one(env,'SELECT notification_chat_id FROM bots WHERE id=? AND tenant_id=?',[id,user.tenant_id]);return json({ok:!!b,paired:!!b?.notification_chat_id});}
  return json({ok:false},404);
}

async function wsWidget(req,env,url){
  if(req.headers.get('Upgrade')!=='websocket')return text('Upgrade required',426);const site=url.searchParams.get('site')||'',vk=url.searchParams.get('visitor_key')||'',d=await widgetSite(env,site);if(!d||!widgetOriginOk(req,d.domain))return text('Forbidden',403);const v=await one(env,'SELECT id FROM visitors WHERE domain_id=? AND visitor_key=?',[d.id,vk]);if(!v)return text('Unknown visitor',404);const stub=hubStub(env,d.id),h=new Headers(req.headers),target=`https://hub/connect?role=visitor&visitor_key=${encodeURIComponent(vk)}`;return stub.fetch(new Request(target,{method:'GET',headers:h}));
}
async function wsDashboard(req,env,url,s,user){
  if(!user||!await can(env,user,'view_chat'))return text('Forbidden',403);if(req.headers.get('Upgrade')!=='websocket')return text('Upgrade required',426);const cid=Number(url.searchParams.get('chat_id')||0),chat=await one(env,'SELECT c.id,c.domain_id FROM chats c JOIN domains d ON d.id=c.domain_id WHERE c.id=? AND d.tenant_id=?',[cid,user.tenant_id]);if(!chat)return text('Not found',404);const stub=hubStub(env,chat.domain_id),h=new Headers(req.headers),target=`https://hub/connect?role=agent&chat_id=${cid}&user_id=${user.id}`;return stub.fetch(new Request(target,{method:'GET',headers:h}));
}

async function mediaRoute(req,env,url,user){if(!user)return text('Unauthorized',401);const key=decodeURIComponent(url.pathname.slice('/media/'.length));const row=await one(env,'SELECT * FROM media_assets WHERE r2_key=? AND (tenant_id=? OR user_id=?)',[key,user.tenant_id,user.id]);if(!row)return text('Not found',404);const obj=await env.UPLOADS.get(key);if(!obj)return text('Not found',404);const h=new Headers();obj.writeHttpMetadata(h);h.set('cache-control','private,max-age=3600');return new Response(obj.body,{headers:h});}
async function widgetMedia(req,env,url){const key=decodeURIComponent(url.pathname.slice('/widget-media/'.length));const row=await one(env,"SELECT * FROM media_assets WHERE r2_key=? AND kind='widget_icon'",[key]);if(!row)return text('Not found',404);const obj=await env.UPLOADS.get(key);if(!obj)return text('Not found',404);const h=new Headers();obj.writeHttpMetadata(h);h.set('cache-control','public,max-age=86400');h.set('access-control-allow-origin','*');return new Response(obj.body,{headers:h});}

async function apiV1(req,env,ctx,url){
  const auth=req.headers.get('authorization')||'',m=auth.match(/^Bearer\s+(.+)$/i);if(!m)return json({ok:false,error:'missing_api_key'},401);const key=m[1],hash=await sha256(key),row=await one(env,"SELECT * FROM api_keys WHERE key_hash=? AND status='active'",[hash]);if(!row)return json({ok:false,error:'invalid_api_key'},401);await run(env,'UPDATE api_keys SET last_used_at=? WHERE id=?',[nowIso(),row.id]);const tid=row.tenant_id;
  if(url.pathname==='/api/v1/chats'&&req.method==='GET'){const chats=await all(env,'SELECT c.*,d.domain FROM chats c JOIN domains d ON d.id=c.domain_id WHERE d.tenant_id=? ORDER BY c.updated_at DESC LIMIT 200',[tid]);return json({ok:true,chats});}
  const mm=url.pathname.match(/^\/api\/v1\/chats\/(\d+)\/messages$/);if(mm&&req.method==='GET'){const chat=await one(env,'SELECT c.id FROM chats c JOIN domains d ON d.id=c.domain_id WHERE c.id=? AND d.tenant_id=?',[Number(mm[1]),tid]);if(!chat)return json({ok:false},404);return json({ok:true,messages:await all(env,'SELECT * FROM messages WHERE chat_id=? ORDER BY id',[chat.id])});}
  if(mm&&req.method==='POST'){const chat=await one(env,'SELECT c.*,v.visitor_key FROM chats c JOIN domains d ON d.id=c.domain_id JOIN visitors v ON v.id=c.visitor_id WHERE c.id=? AND d.tenant_id=?',[Number(mm[1]),tid]);if(!chat)return json({ok:false},404);const b=await req.json().catch(()=>({})),body=String(b.body||'').trim();if(!body)return json({ok:false,error:'body_required'},422);const id=await insert(env,"INSERT INTO messages(chat_id,sender_type,sender_id,body,created_at) VALUES(?,'agent','api',?,?)",[chat.id,cap(body,3500),nowIso()]);await hubBroadcast(env,chat.domain_id,{type:'message',id,chat_id:chat.id,visitor_key:chat.visitor_key,sender_type:'agent',body:cap(body,3500),created_at:nowIso()});await audit(env,ctx,{event:'API_CHAT_REPLY',risk:10,metadata:{chat_id:chat.id},tenantId:tid,request:req});return json({ok:true,id});}
  return json({ok:false,error:'not_found'},404);
}

async function maintenance(env,cron){const t=nowIso(),offline=new Date(Date.now()-120000).toISOString().replace('T',' ').replace('Z','').slice(0,19);await env.DB.batch([
  env.DB.prepare("UPDATE visitors SET status='offline' WHERE last_seen_at<? AND status<>'offline'").bind(offline),
  env.DB.prepare('DELETE FROM sessions WHERE expires_at<?').bind(t),
  env.DB.prepare('DELETE FROM otp_codes WHERE created_at<?').bind(new Date(Date.now()-86400000).toISOString().replace('T',' ').replace('Z','').slice(0,19)),
  env.DB.prepare('DELETE FROM login_attempts WHERE created_at<?').bind(new Date(Date.now()-7*86400000).toISOString().replace('T',' ').replace('Z','').slice(0,19)),
  env.DB.prepare('DELETE FROM rate_limits WHERE expires_at<?').bind(t),
  env.DB.prepare("UPDATE subscriptions SET status='expired' WHERE status IN ('active','trial') AND ends_at<=?").bind(t)
]);
  if(String(cron).includes('17 3')){const subs=await all(env,"SELECT s.tenant_id,p.history_days FROM subscriptions s JOIN plans p ON p.id=s.plan_id WHERE s.status IN ('active','trial') AND s.ends_at>?",[t]);for(const x of subs){const cutoff=new Date(Date.now()-Number(x.history_days||30)*86400000).toISOString().replace('T',' ').replace('Z','').slice(0,19);await run(env,'DELETE FROM messages WHERE chat_id IN (SELECT c.id FROM chats c JOIN domains d ON d.id=c.domain_id WHERE d.tenant_id=?) AND created_at<?',[x.tenant_id,cutoff]);}await run(env,'DELETE FROM pageviews WHERE created_at<?',[new Date(Date.now()-180*86400000).toISOString().replace('T',' ').replace('Z','').slice(0,19)]);}
}
